import { useState } from 'react';
import { JxTagInput, JxChip, JxEmptyState } from '@jinx-ui/react';

interface ArticleTagsProps {
  value?: string[];
  defaultTags?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTags({ value, defaultTags = [], onChange }: ArticleTagsProps) {
  const [inner, setInner] = useState<string[]>(defaultTags);
  const tags = value ?? inner;

  const update = (next: string[]) => {
    if (value === undefined) setInner(next);
    onChange?.(next);
  };

  const add = (next: string[]) => {
    const normalized = next
      .map((tag) => tag.trim())
      .filter((tag, index, all) => tag.length > 0 && all.indexOf(tag) === index);
    update(normalized);
  };

  const remove = (tag: string) => update(tags.filter((item) => item !== tag));

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      <JxTagInput
        ariaLabel="Теги статьи"
        placeholder="Введите тег и нажмите Enter"
        value={tags}
        onValueChange={add}
      />

      {tags.length > 0 ? (
        <div
          role="list"
          aria-label="Выбранные теги"
          style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}
        >
          {tags.map((tag) => (
            <span role="listitem" key={tag}>
              <JxChip
                active
                removable
                onRemove={() => remove(tag)}
                onKeyDown={(event) => {
                  if (event.key === 'Delete' || event.key === 'Backspace') {
                    event.preventDefault();
                    remove(tag);
                  }
                }}
                tabIndex={0}
                aria-label={`Тег ${tag}`}
              >
                {tag}
              </JxChip>
            </span>
          ))}
        </div>
      ) : (
        <JxEmptyState
          title="Тегов пока нет"
          message="Введите ключевое слово в поле выше и нажмите Enter, чтобы добавить первый тег."
        />
      )}
    </div>
  );
}

